CREATE   VIEW [FO].[vwDimensions]
AS
SELECT 
	DAVS.RECID AS [DimensionId]
	,CAST(DAVS.RECID AS NVARCHAR(10)) + '_' + 'DDIM' AS [Dimension Key]
	--,dav.DIMENSIONKEYCOLUMNNAME AS [Dimension Name]
	,davsi.DISPLAYVALUE AS [Cost Center]
FROM synapse_fo.DIMENSIONATTRIBUTEVALUESET DAVS
	LEFT JOIN synapse_fo.DIMENSIONATTRIBUTEVALUESETITEM DAVSI
		ON DAVSI.DIMENSIONATTRIBUTEVALUESET = DAVS.RECID
	LEFT JOIN synapse_fo.DIMENSIONATTRIBUTEVALUE DAVV
		ON DAVV.RECID = DAVSI.DIMENSIONATTRIBUTEVALUE
	LEFT JOIN synapse_fo.DIMENSIONATTRIBUTE DAV
		ON DAV.RECID = DAVV.DIMENSIONATTRIBUTE
WHERE dav.[DIMENSIONKEYCOLUMNNAME] = 'COSTCENTER'

UNION ALL

SELECT 
	T1.[RECID] AS [DimensionId]
	,CAST(T1.RECID AS NVARCHAR(10)) + '_' + 'LDIM' AS [Dimension Key]
	,T1.[COSTCENTER] AS [Cost Center]
FROM synapse_fo.DIMENSIONCOMBINATIONENTITY_RICS T1
